// Student Performance Predictor: core logic (ported from main.py)

// ---- input normaliser (works for Webhook, Form, WhatsApp, Gmail, Sheets and sample data)
const input = $input.all().flatMap(i => {
  const j = i.json || {};
  if (j.messages && Array.isArray(j.messages)) {           // WhatsApp Trigger
    return j.messages.filter(m => m.text).map(m => ({ from: '+' + m.from, text: m.text.body }));
  }
  if (j.Subject !== undefined || j.From !== undefined) {     // Gmail Trigger (simple)
    return [{ from: (j.From || '').replace(/.*<|>.*/g, ''), subject: j.Subject || '', body: j.snippet || j.text || '' }];
  }
  const b = (j.body !== undefined && j.headers !== undefined) ? j.body : j;   // Webhook wraps payload in body
  if (Array.isArray(b)) return b;
  if (b && Array.isArray(b.items)) return b.items;
  return [b];
});

// Coefficients printed by `python main.py` - replace with the ones trained on your school's data.
const MODEL = { intercept: -12.618, attendance: 0.175, assignments: 0.198, midterm: 0.404, study_hours: 1.693 };
const PASS = 50, F = ['attendance', 'assignments', 'midterm', 'study_hours'];
const means = Object.fromEntries(F.map(f => [f, input.reduce((s, r) => s + Number(r[f]), 0) / input.length]));
const rows = input.map(r => { const p = MODEL.intercept + F.reduce((s, f) => s + MODEL[f] * Number(r[f]), 0);
  const weakest = F.reduce((a, f) => ((Number(r[f]) - means[f]) / means[f] < (Number(r[a]) - means[a]) / means[a] ? f : a), F[0]);
  return { name: r.name, predicted: Math.round(p * 10) / 10, at_risk: p < PASS, weakest_factor: weakest }; });
const risk = rows.filter(r => r.at_risk);
return [{ json: { at_risk_count: risk.length, students: rows,
  report: risk.length ? risk.map(r => `${r.name}: predicted ${r.predicted}, weakest factor ${r.weakest_factor}`).join('\n') : 'No students at risk this week.' } }];
